(function() {
  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (!e.isIntersecting) return;
      if (e.target.id === 'z50-tech-feats') {
        e.target.querySelectorAll('.z50-tech__feat').forEach(function(f){ f.classList.add('z50-tech__vis'); });
      } else { e.target.classList.add('z50-tech__vis'); }
      obs.unobserve(e.target);
